  let source=actual.object_member_data("world_rules",&memory,&mut|s,b|facts.work(s,b as usize)).map_err(col)?;
  match source{None=>None,Some(source)=>{let rules=view.share(&source)?;if rules.root_kind()=="null"{Some(rules)}else{
   let owner=match reader{None=>None,Some(reader)=>oasis7_world_state::world_rules::resolve_industrial_owner_readonly_v1(&facts,reader)?};
   let binding=match oasis7_world_state::world_rules::industrial_owner_binding_with_work_v1(owner.as_ref(),&mut|steps,bytes,heap|{facts.work(steps,bytes)?;if heap==0{Ok(())}else{facts.before_owned(heap)}}){Ok(value)=>value.ok(),Err(error)=>return Err(error)};
   let mut out=view.share(&source)?;view.supply(&source,reader,&mut out)?;
   let emergency=view.emergency(view.member(&source,"emergency_supply")?,reader)?;out=view.put(&out,"emergency_supply",Some(&emergency))?;
   let organization=view.organization(view.member(&source,"organization_continuity")?,reader)?;out=view.put(&out,"organization_continuity",Some(&organization))?;
   let original_industrial=view.branch(&source,"industrial_work")?;let industrial=view.industrial(original_industrial.root_data(),reader,binding.as_deref())?;out=view.put(&out,"industrial_work",if view.industrial_empty(&industrial)?{None}else{Some(&industrial)})?;
   let original_substitution=view.branch(&source,"substitution")?;let substitution=view.substitution(original_substitution.root_data(),&industrial,reader,binding.as_deref())?;out=view.put(&out,"substitution",if view.substitution_empty(&substitution)?{None}else{Some(&substitution)})?;
   let roots=view.keys(view.member(&industrial.root_data(),"roots")?)?;let lots=view.keys(view.member(&industrial.root_data(),"lots")?)?;let decisions=view.keys(view.member(&substitution.root_data(),"decisions")?)?;let mut requests=BTreeSet::new();
   facts.visit_rule_rows(C::Requests,|row|{let id=row.original_key_value().as_str().ok_or_else(||invalid("original request key"))?;fact_decode::with_world_rule_receipt_data_v1(facts.raw(row)?,&facts.common,|receipt|{
    if oasis7_world_state::world_rules::current_rule_request_visible_with_work_v1(receipt,reader,binding.as_deref(),&mut|s,b|facts.work(s,b),&mut|reference|view.root_ref(reference,&roots),&mut|reference|view.lot_ref(reference,&lots),&mut|reference|{if !view.contains(&decisions,&reference.id)?{return Ok(false)}match facts.rule_point(C::SubstitutionDecisions,&reference.id)?{None=>Ok(false),Some(row)=>fact_decode::with_substitution_decision_data_v1(facts.raw(row)?,&facts.common,|decision|oasis7_world_state::world_rules::industrial_reference_equal_with_work_v1(&decision.decision_ref,reference,&mut|s,b|facts.work(s,b)))}})?{view.insert(&mut requests,id)?}Ok(())})?;Ok(ControlFlow::Continue(()))})?;
   let request_rows=view.item(&source,"requests")?;let request_rows=view.retain(&request_rows,&requests)?;out=view.put(&out,"requests",Some(&request_rows))?;
   let mut orders=BTreeSet::new();facts.visit_rule_rows(C::AgentOrders,|row|{let id=row.original_key_value().as_str().ok_or_else(||invalid("original order key"))?;fact_decode::with_industrial_order_data_v1(facts.raw(row)?,&facts.common,|order|{facts.work(1,order.owner_id.len()+reader.map_or(0,str::len))?;if reader!=Some(order.owner_id.as_str()){return Ok(())}let owner=oasis7_world_state::world_rules::resolve_industrial_owner_readonly_v1(&facts,&order.owner_id)?;facts.work(1,order.quote.owner_player_id.len()+order.quote.owner_source_id.len()+world_binding.as_deref().map_or(0,str::len))?;if oasis7_world_state::world_rules::can_read_agent_industrial_order_from_owner_v1(order,reader,world_binding.as_deref(),owner.as_ref()){view.insert(&mut orders,id)?}Ok(())})?;Ok(ControlFlow::Continue(()))})?;
   let order_rows=view.item(&source,"agent_orders")?;let order_rows=view.retain(&order_rows,&orders)?;out=view.put(&out,"agent_orders",Some(&order_rows))?;Some(out)
  }}}
